export type MessageStatus = 'sending' | 'sent' | 'delivered' | 'failed';
export type MessageDirection = 'in' | 'out';
export type ConversationType = 'dm' | 'group';

export interface ChatMessage {
  /** UUID generated by the author – globally unique, used to drop duplicates. */
  id: string;
  conversationId: string;
  senderId: string;
  senderNick: string;
  text: string;
  /** Author's timestamp (ms). */
  timestamp: number;
  status: MessageStatus;
  direction: MessageDirection;
  /** Number of distinct nodes that acknowledged (group messages can have many). */
  deliveredCount: number;
  /** Hops travelled (incoming only). */
  hops: number | null;
}

export interface Conversation {
  /** "dm:<nodeId>" or "group:<groupId>" */
  id: string;
  type: ConversationType;
  title: string;
  /** DM counterpart node id. */
  peerId: string | null;
  createdAt: number;
  lastMessageAt: number;
  lastMessagePreview: string;
  unread: number;
}

export const GENERAL_GROUP_ID = 'general';
export const GENERAL_CONVERSATION_ID = `group:${GENERAL_GROUP_ID}`;

export const dmConversationId = (nodeId: string) => `dm:${nodeId}`;
export const groupConversationId = (groupId: string) => `group:${groupId}`;
